CREATE OR REPLACE FUNCTION lab.headcount_under (p_mgr numeric)
RETURNS numeric
LANGUAGE plpgsql
SET search_path = lab, public
AS $$
DECLARE
  l_n numeric;
BEGIN
  WITH RECURSIVE tree AS (
    SELECT emp_id FROM emp WHERE emp_id = p_mgr
    UNION ALL
    SELECT e.emp_id FROM emp e JOIN tree t ON e.mgr_id = t.emp_id
  )
  SELECT count(*) INTO STRICT l_n FROM tree;
  RETURN l_n;
END;
$$;
